function normalizedMovementStage(stage = "") {
  return stage === "Clear" ? "Recruiter Review" : stage === "Onboard" ? "Onboarding" : stage;
}

function isoDateOnly(value = "") {
  if (!value) return "";
  return String(value).slice(0, 10);
}

function candidateProfileCreated(item = {}) {
  return Boolean(
    item.profileCreated ||
      item.profileCreatedAt ||
      item.createdAt ||
      item.submissionDate ||
      item.formSnapshot?.fullName ||
      item.candidate
  );
}

function candidateInterviewDate(item = {}) {
  return isoDateOnly(
    item.interviewDate ||
      item.facilityInterviewDate ||
      item.bookingRecord?.interviewDate ||
      item.bookingRecord?.scheduled_start ||
      item.formSnapshot?.interviewDate ||
      item.rescheduledInterviewDate ||
      item.bookingRecord?.rescheduledDate
  );
}

function interviewDateHasArrived(item = {}) {
  const date = candidateInterviewDate(item);
  if (!date) return false;
  const today = new Date().toISOString().slice(0, 10);
  return date <= today;
}

function movementStageIndex(item = {}) {
  const explicitStage = normalizedMovementStage(item.movementStage);
  const explicitIndex = MOVEMENT_STAGES.indexOf(explicitStage);
  if (explicitIndex >= 0) {
    if (explicitStage === "Submit" && !candidateProfileCreated(item)) return Math.min(explicitIndex, 2);
    if (explicitStage === "Interview" && !candidateInterviewDate(item)) return Math.min(explicitIndex, 3);
    if (explicitStage === "Decision" && !interviewDateHasArrived(item)) return candidateInterviewDate(item) ? 4 : 3;
    return explicitIndex;
  }

  const status = String(item.status || "").toLowerCase();
  const next = String(item.nextAction || "").toLowerCase();
  const joined = `${status} ${next}`;

  if (status.includes("hired")) return 8;
  if (status.includes("onboard")) return 7;
  if (status.includes("offer") || status.includes("verbal")) return 6;
  if (interviewDateHasArrived(item) || status.includes("interview completed") || next.includes("feedback") || next.includes("decision")) return 5;
  if (candidateInterviewDate(item) || status.includes("interview scheduled") || status.includes("interview rescheduled")) return 4;
  if (candidateProfileCreated(item) || status.includes("submitted") || status.includes("awaiting") || status.includes("facility submission")) return 3;
  if (joined.includes("follow") || joined.includes("hold") || joined.includes("escalation") || joined.includes("review")) return 2;
  if (item.screenCompletedAt || status.includes("screen complete")) return 1;
  return 0;
}

function movementStageForItem(item = {}) {
  return MOVEMENT_STAGES[movementStageIndex(item)] || "Lead";
}

function movementPatchForStage(stage, item = {}) {
  stage = normalizedMovementStage(stage);
  const stageRules = MOVEMENT_STAGE_STATUS_MAP[stage] || MOVEMENT_STAGE_STATUS_MAP.Lead;
  const patch = {
    movementStage: stage,
    status: stageRules.status || item.status || "Recruiter Review",
    nextAction: stageRules.nextAction || item.nextAction || "Continue workflow",
  };
  if (stage === "Submit") {
    patch.profileCreated = true;
    patch.profileCreatedAt = item.profileCreatedAt || new Date().toISOString();
  }
  return patch;
}

function pipelineProgressionForItem(item = {}) {
  if (item.closedFromPipelineStep) return item.closedFromPipelineStep;
  const status = String(item.status || "");
  const action = String(item.nextAction || "");
  const text = `${status} ${action}`.toLowerCase();
  if (/hired|start confirmed/.test(text)) return "Hired";
  if (/cleared to start/.test(text)) return "Cleared to Start";
  if (/onboard|application|credentialing|background|clearance/.test(text)) return "Onboarding Started";
  if (/offer/.test(text)) return "Offer/Next Steps";
  if (interviewDateHasArrived(item) || /decision|selected|not selected|feedback|interview completed/.test(text)) return "Decision Pending";
  if (candidateInterviewDate(item) || /interview scheduled|confirm interview|reminder|rescheduled|canceled|no show/.test(text)) return "Interview Scheduled";
  if (/interview requested|schedule interview|availability/.test(text)) return "Interview Outreach";
  if (/submitted|facility submission/.test(text) || candidateProfileCreated(item)) return "Facility Submission";
  if (/awaiting review|being reviewed|follow-up due|escalation|manager|leadership/.test(text)) return "Facility Review";
  if (/review|document|license|qualification|clear/.test(text)) return "Recruiter Review";
  if (/screen complete/.test(text)) return "Screen Complete";
  if (/screen scheduled/.test(text)) return "Screen Scheduled";
  if (/outreach|follow up/.test(text)) return "Outreach Started";
  return "Lead Added";
}

function activePeopleContacts(settings = {}) {
  return (settings.contacts || []).filter((contact) => contact && contact.status !== "Inactive" && (contact.department || contact.duty || contact.name || contact.email));
}

function departmentLabelForContact(contact = {}) {
  return contact.department || contact.duty || contact.title || "People & Contacts";
}

function contactLabelForToken(contact = {}) {
  return [contact.name || contact.title || contact.department || "Contact", contact.title && contact.name ? contact.title : "", contact.email].filter(Boolean).join(" | ");
}

function contactRecipientPresetOptions(settings = {}) {
  const options = [];
  const groups = {};
  activePeopleContacts(settings).forEach((contact) => {
    const department = departmentLabelForContact(contact);
    const departmentSlug = tokenKeySlug(department);
    const personSlug = tokenKeySlug(contact.name || contact.title || contact.duty || department);
    groups[departmentSlug] = groups[departmentSlug] || { label: department, contacts: [] };
    groups[departmentSlug].contacts.push({ contact, personSlug });
  });
  Object.entries(groups).forEach(([departmentSlug, group]) => {
    options.push({ value: `department:${departmentSlug}`, label: `People & Contacts - ${group.label}` });
    group.contacts.forEach(({ contact, personSlug }) => {
      options.push({ value: `person:${departmentSlug}:${personSlug}`, label: `${group.label} - ${contactLabelForToken(contact)}` });
    });
  });
  return options;
}

function activeSubmissionStepKeysFor(settings = {}) {
  const templateActive = (key) => String((settings.templates || {})[key]?.status || "Active").toLowerCase() === "active";
  const keys = [
    templateActive("hiringManager") ? "manager" : "",
    templateActive("candidateConfirmation") ? "candidate" : "",
    templateActive("atsUpdate") ? "ats" : "",
  ].filter(Boolean);
  return keys.length ? keys : ["manager", "candidate", "ats"];
}

function templateRecordForSettings(settings = {}, key = "") {
  const base = { useCustom: false, subject: "", body: "", ...(DEFAULT_SETTINGS.templates?.[key] || {}) };
  const saved = (settings.templates || {})[key] || {};
  return {
    ...base,
    ...saved,
    conditionalBlocks: {
      ...(base.conditionalBlocks || {}),
      ...(saved.conditionalBlocks || {}),
    },
  };
}

function renderWorkflowTemplate(record = {}, values = {}, fallback = {}) {
  return {
    subject: applyTokens(record.subject || fallback.subject || "", values, record),
    body: applyTokens(record.body || fallback.body || "", values, record),
    to: applyTokens(record.to || fallback.to || "", values, record),
    cc: applyTokens(record.cc || fallback.cc || "", values, record),
    from: applyTokens(record.from || fallback.from || "{recruiter_email}", values, record),
    channel: record.channel || fallback.channel || "Email",
  };
}

function managerEmailFor(settings = {}, item = {}) {
  return item.managerEmail || item.hiringManagerEmail || settings.general?.hiringManagerEmail || settings.general?.recruiterEmail || "";
}

function managerPhoneFor(settings = {}, item = {}) {
  return item.managerPhone || settings.general?.hrContactPhone || settings.general?.recruiterPhone || "";
}

function managerRecipientsFor(settings = {}, item = {}) {
  return cleanEmailList([managerEmailFor(settings, item), item.facilityContactEmail, item.hrContactEmail].filter(Boolean).join(";"));
}

function facilityRecipientEmailsFor(settings = {}, facility = "") {
  const site = siteRecordFor(settings, facility);
  return cleanEmailList([site.hiringManagerEmail, site.adminContactEmail, ...(site.additionalHiringManagers || []).map((manager) => manager.email)].filter(Boolean).join(";"));
}

function facilityRecipientsFor(settings = {}, facility = "") {
  return facilityRecipientEmailsFor(settings, facility).join("; ");
}

function labelFromKey(key = "") {
  const special = { fte: "FTE", cprStatus: "CPR/BLS Status", reqNumber: "Req Number", uniqueIdNumber: "Unique ID Number", siteName: "Facility", atsUpdate: "ATS Update" };
  if (special[key]) return special[key];
  return String(key).replace(/([A-Z])/g, " $1").replace(/^./, (char) => char.toUpperCase()).trim();
}

function headerKey(label = "") {
  return String(label || "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
}

function normalizeCsvHeader(row = {}, aliases = []) {
  const keys = Object.keys(row || {});
  const wanted = (Array.isArray(aliases) ? aliases : [aliases]).map((item) => headerKey(item));
  const match = keys.find((key) => wanted.includes(headerKey(key)));
  return match ? row[match] : "";
}

function truthySpreadsheetValue(value) {
  return ["yes", "true", "1", "x", "required", "active"].includes(String(value || "").trim().toLowerCase());
}

function parseDelimitedRows(text = "") {
  const lines = String(text || "").split(/\r?\n/).filter((line) => line.trim());
  if (!lines.length) return [];
  const delimiter = lines[0].includes("\t") ? "\t" : ",";
  const parseLine = (line) => {
    const cells = [];
    let current = "";
    let quoted = false;
    for (let index = 0; index < line.length; index += 1) {
      const char = line[index];
      if (char === '"' && line[index + 1] === '"') { current += '"'; index += 1; }
      else if (char === '"') quoted = !quoted;
      else if (char === delimiter && !quoted) { cells.push(current.trim()); current = ""; }
      else current += char;
    }
    cells.push(current.trim());
    return cells;
  };
  const headers = parseLine(lines[0]);
  return lines.slice(1).map((line) => {
    const values = parseLine(line);
    return headers.reduce((record, header, index) => ({ ...record, [header]: values[index] || "" }), {});
  });
}

function spreadsheetRowsFromInput(input = "") {
  if (Array.isArray(input)) return input;
  return parseDelimitedRows(input);
}

function toCsv(rows = [], columns = []) {
  const escape = (value) => {
    const clean = String(value ?? "");
    return /[",\n]/.test(clean) ? `"${clean.replace(/"/g, '""')}"` : clean;
  };
  return [columns.map(escape).join(","), ...rows.map((row) => columns.map((column) => escape(row[column])).join(","))].join(NL);
}

function readFileText(file, onText) {
  const promise = new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error);
    reader.readAsText(file);
  });
  if (onText) promise.then(onText).catch(() => onText(""));
  return promise;
}

const STANDARD_RESUME_FILE_ACCEPT = ".pdf,.doc,.docx,.rtf,.txt,.text,.csv,.tsv,.xlsx,.xls,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/rtf,text/rtf,text/plain,text/csv,text/tab-separated-values";

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || "").split(",").pop() || "");
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

async function parseResumeFileWithApi(file) {
  if (!file || typeof fetch !== "function") return null;
  try {
    const base64 = await fileToBase64(file);
    const response = await fetch("/api/parse-resume", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ filename: file.name || "resume", mimeType: file.type || "application/octet-stream", size: file.size || 0, base64 }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload?.ok === false) throw new Error(payload?.error || "Resume parser unavailable");
    return { __resumeParserResult: true, provider: payload.provider || "WelcomeFlow Parser", text: payload.text || "", fields: payload.fields || {}, confidence: payload.confidence || 0, warnings: payload.warnings || [] };
  } catch (error) {
    return null;
  }
}

async function extractResumeFileText(file) {
  if (!file) return "";
  const name = String(file.name || "").toLowerCase();
  const type = String(file.type || "").toLowerCase();
  const apiResult = await parseResumeFileWithApi(file);
  if (apiResult?.text || Object.keys(apiResult?.fields || {}).length) return apiResult;
  if (name.endsWith(".pdf") || type === "application/pdf") {
    try {
      const data = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data }).promise;
      const pages = [];
      for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
        const page = await pdf.getPage(pageNumber);
        const content = await page.getTextContent();
        pages.push(content.items.map((item) => item.str).join(" "));
      }
      return pages.join(NL).trim();
    } catch {
      return "";
    }
  }
  if (name.endsWith(".txt") || name.endsWith(".csv") || name.endsWith(".tsv") || /text\//.test(type)) return readFileText(file);
  return "";
}

