function makeId(prefix = "id") {
  return `${prefix}-${Math.random().toString(36).slice(2, 10)}`;
}

function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

function addDaysIso(value, days = 0) {
  const date = value ? new Date(`${value}T12:00:00`) : new Date();
  if (Number.isNaN(date.getTime())) return todayIso();
  date.setDate(date.getDate() + Number(days || 0));
  return date.toISOString().slice(0, 10);
}

function displayDate(value) {
  if (!value) return "N/A";
  const clean = String(value).slice(0, 10);
  const date = new Date(`${clean}T12:00:00`);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleDateString("en-US");
}

function loadStoredValue(key, fallback) {
  try {
    if (typeof window === "undefined") return fallback;
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function saveStoredValue(key, value) {
  try {
    if (typeof window !== "undefined") window.localStorage.setItem(key, JSON.stringify(value));
  } catch {}
}

async function loadCloudWorkspaceState() {
  if (!supabase) return { data: null, error: "Supabase not configured" };
  const { data, error } = await supabase.from(CLOUD_TABLE).select("data").eq("workspace_id", CLOUD_WORKSPACE_ID).maybeSingle();
  return { data: data?.data || null, error };
}

async function saveCloudWorkspaceState(data) {
  if (!supabase) return { error: "Supabase not configured" };
  const result = await saveWorkspacePreservingCommunicationDraftsToCloud({
    client: supabase,
    table: CLOUD_TABLE,
    workspaceId: CLOUD_WORKSPACE_ID,
    runtime: { environment: runtimeConfig.environment, projectRef: runtimeConfig.projectRef },
    workspaceState: data,
    normalizeSettings: (value) => normalizeSettings(mergeDefaults(DEFAULT_SETTINGS, value || {})),
  });
  return { error: result.ok ? null : result.error };
}

function buildWorkspaceState(settings, tracker, history, notesText, manualQueueItems, hotLeads, reportHistory, reportInclusions, intakeDraft, intakeDrafts, hotLeadBulkDrafts) {
  return { settings, tracker, history, notesText, manualQueueItems, hotLeads, reportHistory, reportInclusions, intakeDraft, intakeDrafts, hotLeadBulkDrafts, savedAt: new Date().toISOString() };
}

function normalizeCommonSpelling(value = "") {
  return String(value || "")
    .replace(/Health Service Administrator/gi, "Health Services Administrator")
    .replace(/Nurse Adminstrator/gi, "Nurse Administrator")
    .replace(/credentailing|creditialing|credeitaling/gi, "credentialing")
    .trim();
}

function cleanRateText(value = "") {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function inferRateScopeType(value = "") {
  const clean = String(value || "").toLowerCase();
  if (!clean || clean === "all") return "All";
  if (clean.includes("operation") || clean.includes("site type") || clean.includes("mission")) return "Site Type";
  return "Site";
}

function cleanEmailList(value = "") {
  return Array.from(new Set(String(value || "").split(/[;,\s]+/).map((item) => item.trim()).filter((item) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(item))));
}

function contactByDuty(settings = {}, duty = "") {
  const needle = String(duty || "").toLowerCase();
  return (settings.contacts || []).find((contact) => [contact.duty, contact.department, contact.title, contact.name].some((field) => String(field || "").toLowerCase().includes(needle))) || null;
}

function contactEmailFor(settings = {}, duty = "") {
  return contactByDuty(settings, duty)?.email || "";
}

function facilityNameFromContext(facility = "") {
  if (typeof facility === "string") return facility;
  if (!facility || typeof facility !== "object") return "";
  const snapshot = facility.formSnapshot || {};
  return facility.siteName || facility.site || facility.facility || facility.selectedFacility || facility.location || snapshot.siteName || snapshot.facility || "";
}

function siteRecordFor(settings = {}, facility = "") {
  const target = normalizeFacilityName(facilityNameFromContext(facility));
  return (settings.sites || []).find((row) => normalizeFacilityName(row.siteName || "") === target) || {};
}

function contactLineForPerson(person = {}, fallback = "Facility Contact") {
  if (!person.name && !person.title && !person.email && !person.phone) return "";
  return `${person.name || fallback}${person.title ? ` | ${person.title}` : ""}${person.email ? ` | ${person.email}` : ""}${person.phone ? ` | ${person.phone}` : ""}`;
}

function siteContactLinesFor(settings = {}, facility = "") {
  const site = siteRecordFor(settings, facility);
  const contacts = [
    contactLineForPerson({ name: site.hiringManagerName, title: site.hiringManagerTitle, email: site.hiringManagerEmail, phone: site.hiringManagerPhone }, "Hiring Manager"),
    ...(site.additionalHiringManagers || []).map((manager) => contactLineForPerson(manager, "Additional Manager")),
    contactLineForPerson({ name: site.adminContactName, title: "Administrative Contact", email: site.adminContactEmail, phone: site.adminContactPhone }, "Administrative Contact"),
  ].filter(Boolean);
  return contacts.length ? contacts.join(NL) : "No facility contacts listed.";
}

function siteContactDetailLinesFor(settings = {}, facility = "") {
  return siteContactLinesFor(settings, facility);
}

function departmentContactLinesFor(settings = {}) {
  return (settings.contacts || []).filter((contact) => contact.status !== "Inactive").map((contact) => `${contact.name || contact.department || "Contact"}${contact.title ? ` | ${contact.title}` : ""}${contact.email ? ` | ${contact.email}` : ""}`).join(NL) || "No department contacts listed.";
}

function tokenKeySlug(value = "") {
  return normalizedWords(value).replace(/\s+/g, "_").replace(/^_+|_+$/g, "") || "contact";
}

function contactTokenValues(settings = {}) {
  const values = {};
  const groups = {};
  const add = (key, value) => {
    if (!key || values[key] !== undefined) return;
    values[key] = value || "";
  };
  activePeopleContacts(settings).forEach((contact) => {
    const department = departmentLabelForContact(contact);
    const departmentSlug = tokenKeySlug(department);
    const personSlug = tokenKeySlug(contact.name || contact.title || contact.duty || department);
    const prefix = `contact_${departmentSlug}_${personSlug}`;
    groups[departmentSlug] = groups[departmentSlug] || { label: department, contacts: [] };
    groups[departmentSlug].contacts.push(contact);
    add(prefix, contactLineForPerson(contact, department));
    add(`${prefix}_name`, contact.name || contact.title || department);
    add(`${prefix}_title`, contact.title || contact.duty || department);
    add(`${prefix}_email`, contact.email || "");
    add(`${prefix}_phone`, contact.phone || "");
  });
  Object.entries(groups).forEach(([departmentSlug, group]) => {
    const contacts = group.contacts || [];
    const lines = contacts.map((contact) => contactLineForPerson(contact, group.label)).filter(Boolean);
    const emails = cleanEmailList(contacts.map((contact) => contact.email).filter(Boolean).join("; ")).join("; ");
    const names = contacts.map((contact) => contact.name || contact.title || contact.department).filter(Boolean).join("; ");
    const primary = contacts[0] || {};
    add(`department_${departmentSlug}_contacts`, lines.join(NL));
    add(`department_${departmentSlug}_emails`, emails);
    add(`department_${departmentSlug}_names`, names);
    add(`${departmentSlug}_contacts`, lines.join(NL));
    add(`${departmentSlug}_emails`, emails);
    add(`${departmentSlug}_names`, names);
    add(`${departmentSlug}_contact_name`, primary.name || primary.title || group.label);
    add(`${departmentSlug}_contact_email`, primary.email || "");
  });
  return values;
}

function contactTokenOptions(settings = {}) {
  const options = [];
  const groups = {};
  activePeopleContacts(settings).forEach((contact) => {
    const department = departmentLabelForContact(contact);
    const departmentSlug = tokenKeySlug(department);
    const personSlug = tokenKeySlug(contact.name || contact.title || contact.duty || department);
    groups[departmentSlug] = groups[departmentSlug] || { label: department, contacts: [] };
    groups[departmentSlug].contacts.push({ contact, personSlug });
  });
  Object.entries(groups).forEach(([departmentSlug, group]) => {
    options.push({ value: `{department_${departmentSlug}_contacts}`, label: `People & Contacts - ${group.label}: full contact list` });
    options.push({ value: `{department_${departmentSlug}_emails}`, label: `People & Contacts - ${group.label}: email list` });
    options.push({ value: `{${departmentSlug}_contact_phone}`, label: `${group.label}: primary phone` });
    options.push({ value: `{${departmentSlug}_contact_email}`, label: `${group.label}: primary email` });
    group.contacts.forEach(({ contact, personSlug }) => {
      const base = `contact_${departmentSlug}_${personSlug}`;
      const label = contactLabelForToken(contact);
      options.push({ value: `{${base}_email}`, label: `${group.label} - ${label}: email` });
      options.push({ value: `{${base}_phone}`, label: `${group.label} - ${label}: phone` });
      options.push({ value: `{${base}}`, label: `${group.label} - ${label}: full contact` });
    });
  });
  return options;
}

function rehireDetailsText(form = {}, prefix = "- ") {
  const isRehire = form.previousEmployee === "Yes" || ["Internal", "Rehire"].includes(form.candidateType);
  if (!isRehire) return "";
  return [
    `Candidate Type: ${form.candidateType || "N/A"}`,
    `Previous Employee: ${form.previousEmployee || "No"}`,
    form.previousFacility ? `Previous Facility: ${form.previousFacility}` : "",
    form.previousRole ? `Previous Role: ${form.previousRole}` : "",
    form.previousManager ? `Previous Manager: ${form.previousManager}` : "",
    form.previousEmploymentDates ? `Previous Employment Dates: ${form.previousEmploymentDates}` : "",
    form.separationReason ? `Separation Reason: ${form.separationReason}` : "",
    form.separationType ? `Separation Type: ${form.separationType}` : "",
    form.priorPayRate ? `Prior Pay Rate: ${form.priorPayRate}` : "",
    form.rehireEligibility ? `Rehire Eligibility: ${form.rehireEligibility}` : "",
    form.hrReviewStatus ? `HR Review Status: ${form.hrReviewStatus}` : "",
    form.hrEligibilityEmailSent || form.hrRequestSentAt ? "HR Eligibility Email: Sent" : "",
    form.priorPerformanceConcerns ? `Prior Performance Concerns: ${form.priorPerformanceConcerns}` : "",
    form.rehireWarningOptOut || form.rehireEligibilityBypassed ? "Eligibility Hold Bypassed: Yes" : "",
  ].filter(Boolean).map((line) => `${prefix}${line}`).join(NL);
}

function ensureRehireDetailsInBody(body = "", form = {}) {
  const details = rehireDetailsText(form);
  if (!details) return body;
  const text = String(body || "");
  if (text.includes(details) || /\{rehire_details\}|REHIRE \/ INTERNAL VERIFICATION|Rehire\/Internal Verification/i.test(text)) return text;
  return [text.trim(), "", "REHIRE / INTERNAL VERIFICATION", details].filter(Boolean).join(NL);
}

function screeningAnswersText(form = {}, questions = []) {
  const answers = form.siteSpecificAnswers || form.screeningAnswers || {};
  if (typeof answers === "string") return answers.trim();
  return normalizeScreeningQuestions(questions)
    .map((question) => {
      const answer = answers[question.id];
      if (answer === undefined || answer === "") return "";
      const match = question.matchText && String(answer).toLowerCase().includes(String(question.matchText).toLowerCase()) ? " | Match" : "";
      return `- ${question.question}: ${answer}${match}`;
    })
    .filter(Boolean)
    .join(NL);
}

function emailSignOffLines(settings = {}) {
  const general = settings.general || {};
  return [
    general.includeSignOffNameInEmails === false ? "" : (general.signOffName || general.recruiterName || ""),
    general.includeSignatureLineInEmails === false ? "" : (general.signOffLine || ""),
  ].filter(Boolean);
}

