function tokenMap(form = {}, settings = {}, extra = {}) {
  form = form || {};
  const candidateName = form.fullName || form.candidate || "Candidate";
  const facilityContext = form.siteName || form.site || form.facility || form.formSnapshot?.siteName || form;
  const facilityContactLines = extra.facilityContacts || siteContactDetailLinesFor(settings, facilityContext);
  const facilityContactEmails = extra.facilityContactEmails || facilityRecipientsFor(settings, facilityContext);
  const phoneScreenDateRaw = extra.phoneScreenDate || extra.bookedScreeningDate || form.phoneScreenDate || form.bookedScreeningDate || form.hotLeadBookedScreeningDate || form.formSnapshot?.hotLeadBookedScreeningDate || form.formSnapshot?.bookedScreeningDate || "";
  const phoneScreenTimeRaw = extra.phoneScreenTime || extra.bookedScreeningTime || form.phoneScreenTime || form.bookedScreeningTime || form.hotLeadBookedScreeningTime || form.formSnapshot?.hotLeadBookedScreeningTime || form.formSnapshot?.bookedScreeningTime || "";
  const phoneScreenDateText = phoneScreenDateRaw ? displayDate(phoneScreenDateRaw) : "Not scheduled";
  const phoneScreenTimeText = phoneScreenTimeRaw || "Not scheduled";
  const backgroundContact = contactByDuty(settings, "Background Check") || contactByDuty(settings, "Background") || {};
  const credentialText = extra.credentials || [
    form.licenseType ? `License/Certification: ${form.licenseType}` : "",
    form.licenseStatus ? `Status: ${form.licenseStatus}` : "",
    form.cprStatus ? `CPR: ${form.cprStatus}` : "",
    form.licensedYear ? `Year Licensed: ${form.licensedYear}` : "",
  ].filter(Boolean).join(" | ");
  return {
    candidate_name: candidateName,
    candidate_first_name: String(candidateName || "Candidate").trim().split(/\s+/)[0] || "Candidate",
    position: form.position || form.positionTitle || "position",
    facility: form.siteName || form.site || form.facility || settings.general?.companyName || "the facility",
    employment_type: form.employmentType || "Employment Type",
    shift: form.shiftPreference || form.shift || "Shift",
    req_number: form.reqNumber || "N/A",
    unique_id_number: form.uniqueIdNumber || "N/A",
    candidate_source: form.candidateSource || "N/A",
    candidate_type: form.candidateType || "N/A",
    previous_employee: form.previousEmployee || "No",
    rehire_eligibility: form.rehireEligibility || "Not needed",
    experience: experienceLabelFor(form),
    education: buildEducation(form),
    credentials: credentialText || "N/A",
    start_date: form.startAvailability || "N/A",
    tentative_start_date: extra.tentativeStartDate || form.tentativeStartDate || form.startDate || "Pending",
    tentative_transfer_date: extra.tentativeTransferDate || form.tentativeTransferDate || form.tentativeStartDate || form.startDate || "Pending",
    interview_availability: form.interviewAvailability || "N/A",
    phone_screen_date: phoneScreenDateText,
    phone_screen_time: phoneScreenTimeText,
    phone_screen_datetime: phoneScreenDateRaw ? `${phoneScreenDateText}${phoneScreenTimeRaw ? ` at ${phoneScreenTimeRaw}` : ""}` : "Not scheduled",
    booked_screening_date: phoneScreenDateText,
    booked_screening_time: phoneScreenTimeText,
    booked_screening_datetime: phoneScreenDateRaw ? `${phoneScreenDateText}${phoneScreenTimeRaw ? ` at ${phoneScreenTimeRaw}` : ""}` : "Not scheduled",
    work_type: form.workType || "N/A",
    fte: fteLabel(form.fte),
    interview_date: extra.interviewDateText || (extra.interviewDate ? displayDate(extra.interviewDate) : (form.interviewDate ? displayDate(form.interviewDate) : "Not listed")),
    rescheduled_date: extra.rescheduledDate ? displayDate(extra.rescheduledDate) : (form.rescheduledInterviewDate ? displayDate(form.rescheduledInterviewDate) : "Not listed"),
    recruiter_name: settings.general?.signOffName || settings.general?.recruiterName || "",
    recruiter_email: settings.general?.recruiterEmail || "",
    hr_contact_name: settings.general?.hrContactName || "HR Team",
    hr_contact_email: settings.general?.hrContactEmail || "",
    hr_contact_phone: settings.general?.hrContactPhone || "",
    facility_contacts: facilityContactLines,
    facility_leadership: facilityContactLines,
    facility_contact_email: facilityContactEmails,
    facility_leadership_emails: facilityContactEmails,
    department_contacts: extra.departmentContacts || departmentContactLinesFor(settings),
    background_contact_name: backgroundContact.name || backgroundContact.title || "Background Check Team",
    background_contact_email: contactEmailFor(settings, "Background Check"),
    credentialing_contact_email: contactEmailFor(settings, "Credentialing"),
    hr_onboarding_email: contactEmailFor(settings, "Offer Letter") || settings.general?.hrContactEmail || "",
    candidate_email: form.emailAddress || form.candidateEmail || "",
    candidate_phone: form.phoneNumber || form.candidatePhone || "",
    application_link: extra.applicationLink || form.applicationLink || form.onboardingApplicationLink || settings.general?.defaultApplicationLink || settings.general?.defaultBookingLink || "Application link needed",
    candidate_notes: form.candidateNotes || "",
    status: extra.status || form.status || "Submitted",
    next_action: extra.nextAction || form.nextAction || "Awaiting manager review",
    submission_date: displayDate(extra.submissionDate || todayIso()),
    final_compensation: extra.final_compensation || extra.finalComp || form.estimatedCompensation || form.approvedRate || "",
    ...contactTokenValues(settings),
    ...extra,
  };
}

function candidateFitForReq(req, form = {}, resumeText = "") {
  if (!req) return { score: 0, reasons: ["Select a requisition to score fit."], missing: ["Requisition"] };
  const resume = String(resumeText || "").toLowerCase();
  const formText = Object.values(form || {}).filter((value) => typeof value === "string").join(" ").toLowerCase();
  const text = `${resume} ${formText}`;
  const sameText = (left, right) => String(left || "").trim().toLowerCase() === String(right || "").trim().toLowerCase();
  const employmentMatches = sameText(form.employmentType, req.employmentType) || (String(form.employmentType || "").toLowerCase().includes("prn") && String(req.employmentType || "").toLowerCase().includes("prn"));
  const credentialVerified = /active|clear|verified|yes|required|rn|lpn|cna|certification|bls|cpr|acls/.test(text);
  const cprVerified = /active|verified|yes|bls|cpr/.test(`${form.cprStatus || ""} ${text}`.toLowerCase());
  let points = 0;
  let possible = 0;
  const reasons = [];
  const missing = [];
  const add = (condition, weight, yes, no) => {
    possible += weight;
    if (condition) {
      points += weight;
      if (yes) reasons.push(yes);
    } else if (no) {
      missing.push(no);
    }
  };
  add(form.position && req.positionTitle && sameText(form.position, req.positionTitle), 18, `Position matches ${req.positionTitle}.`, "Position match");
  add(form.siteName && req.siteName && sameText(form.siteName, req.siteName), 10, `Facility matches ${req.siteName}.`, "Facility match");
  add(form.employmentType && req.employmentType && employmentMatches, 8, `Employment type matches ${req.employmentType}.`, "Employment type");
  add(form.shiftPreference && req.shiftPreference && sameText(form.shiftPreference, req.shiftPreference), 8, `Shift matches ${req.shiftPreference}.`, "Shift preference");
  add(form.roleCategory && req.roleCategory && sameText(form.roleCategory, req.roleCategory), 6, `Role category matches ${req.roleCategory}.`, "Role category");
  const reqText = `${req.requiredInfo || ""} ${req.credentialRequirements || ""} ${req.notes || ""}`.toLowerCase();
  add(!/license|rn|lpn|cna|certification/.test(reqText) || credentialVerified, 14, "Credential language appears aligned.", "Credential evidence");
  add(!/cpr|bls/.test(reqText) || cprVerified, 8, "CPR/BLS evidence appears in the candidate data.", "CPR/BLS evidence");
  normalizeScreeningQuestions(req.screeningQuestions).forEach((question) => {
    const answer = form.siteSpecificAnswers?.[question.id] || "";
    const match = question.matchText ? new RegExp(question.matchText.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i").test(`${answer} ${text}`) : Boolean(answer);
    add(match, 8, `${question.question} appears to match.`, question.question);
  });
  const score = possible ? Math.round((points / possible) * 100) : 0;
  return { score, reasons: reasons.slice(0, 5), missing: missing.slice(0, 5) };
}

function applyTokens(template, values) {
  return String(template || "").replace(/\{([a-zA-Z0-9_]+)\}/g, (_, key) => values[key] ?? "");
}

function formLikeFromCandidate(item = {}) {
  const snapshot = item.formSnapshot || {};
  return {
    ...snapshot,
    fullName: item.candidate || snapshot.fullName || "",
    emailAddress: item.candidateEmail || snapshot.emailAddress || "",
    phoneNumber: item.candidatePhone || snapshot.phoneNumber || "",
    position: item.position || snapshot.position || "",
    siteName: item.site || snapshot.siteName || "",
    employmentType: snapshot.employmentType || item.employmentType || "",
    shiftPreference: snapshot.shiftPreference || item.shift || "",
    reqNumber: item.reqNumber || snapshot.reqNumber || "",
    candidateSource: item.candidateSource || snapshot.candidateSource || "",
    candidateNotes: snapshot.candidateNotes || item.notes || "",
    applicationLink: item.applicationLink || item.onboardingApplicationLink || snapshot.applicationLink || snapshot.onboardingApplicationLink || "",
  };
}

