    const lead = sourceLeads.find((item) => item.id === reqAssignmentDraft.leadId);
    if (liveMode && lead?.raw && onUpdateLeadField) {
      onUpdateLeadField(lead.raw.id, "selectedRequisitionId", reqAssignmentDraft.reqId);
      setCopyNotice("Lead tied to requisition details.");
    } else {
      mockNotice("Lead tied to requisition details");
    }
    setReqAssignmentDraft(null);
