    runLeadAction((lead) => onSaveScreenSchedule ? onSaveScreenSchedule(lead, screenScheduleDraft, startAfterSave) : null, startAfterSave ? "Screen saved and started" : "Screen schedule saved");
    setScreenScheduleDraft(null);
