function IntakeStepShell({ stepKey, activeStep, title, subtitle, children, onOpen, onComplete, onBack, onSaveProgress, isComplete, completeLabel = "Complete & Next", statusLabel, statusTone, hideFooter = false, onWithdraw, withdrawalOpen = false, withdrawalReason = "", withdrawalReasonOptions = [], withdrawalNote = "", onWithdrawalReasonChange, onWithdrawalNoteChange, onConfirmWithdraw }) {
  const open = stepKey === activeStep;
  if (!open) return null;
  const nextButtonStyle = { background: "linear-gradient(135deg, #4c1d95 0%, #6d28d9 120%)", borderColor: THEME.primary2, color: "#ffffff", boxShadow: "0 12px 24px rgba(91,33,182,0.22)" };
  const withdrawalNeedsNote = withdrawalReason === "Other";
  const withdrawalReady = Boolean(withdrawalReason) && (!withdrawalNeedsNote || Boolean(String(withdrawalNote || "").trim()));
  return (
    <div style={{ border: `1px solid ${open ? THEME.primary2 : THEME.borderSoft}`, borderRadius: 6, background: THEME.panel, overflow: "hidden", boxShadow: open ? "0 14px 26px rgba(42,24,98,0.08)" : "none" }}>
      <button type="button" onClick={onOpen} style={{ width: "100%", border: "none", background: open ? THEME.panelAlt : THEME.panel, padding: open ? "14px 16px" : "11px 13px", display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center", cursor: "pointer", textAlign: "left" }}>
        <span style={{ display: "grid", gridTemplateColumns: "26px 1fr", gap: 10, alignItems: "center" }}>
          <span style={{ width: 26, height: 26, borderRadius: 6, display: "grid", placeItems: "center", background: open ? THEME.blueBg : THEME.panelAlt, color: THEME.primary2, fontWeight: 950, fontSize: 12 }}>{title.slice(0, 1)}</span>
          <span>
          <span style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontWeight: 900, color: THEME.text, fontSize: open ? 14 : 12.5 }}>
            {title}
          </span>
          {subtitle ? <span style={{ display: "block", color: THEME.muted, fontSize: open ? 12 : 11, marginTop: 3 }}>{subtitle}</span> : null}
          </span>
        </span>
        <span style={{ display: "inline-flex", alignItems: "center", padding: "5px 9px", borderRadius: open ? 999 : 6, background: open ? THEME.blueBg : THEME.panelAlt, color: THEME.primary2, fontSize: 11, fontWeight: 900, whiteSpace: "nowrap" }}>{open ? "Open" : "Review"}</span>
      </button>
      <div style={{ padding: 14, borderTop: `1px solid ${THEME.borderSoft}`, display: "grid", gap: 14 }}>
        {children}
        {hideFooter ? null : (
          <div style={{ display: "grid", gap: 10 }}>
            {withdrawalOpen ? (
              <div style={{ border: `1px solid ${THEME.red}`, borderRadius: 6, padding: 12, background: THEME.redBg, display: "grid", gap: 10 }}>
                <div>
                  <strong>Candidate withdrew from intake</strong>
                  <div style={{ color: THEME.muted, fontSize: 12, marginTop: 3 }}>Add the withdrawal details. WelcomeFlow will archive the incomplete profile so it can be found again later.</div>
                </div>
                <Field label="Withdrawal Reason">
                  <SelectInput value={withdrawalReason} onChange={(event) => onWithdrawalReasonChange?.(event.target.value)} options={withdrawalReasonOptions} placeholder="Select why the candidate withdrew" />
                </Field>
                <Field label={withdrawalNeedsNote ? "Notes (required for Other)" : "Notes (optional)"}>
                  <TextArea value={withdrawalNote} onChange={(event) => onWithdrawalNoteChange?.(event.target.value)} minHeight={78} placeholder="Add any helpful context for history, reporting, or future review." />
                </Field>
                <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, flexWrap: "wrap" }}>
                  <Button subtle onClick={onWithdraw}>Cancel</Button>
                  <Button danger onClick={onConfirmWithdraw} disabled={!withdrawalReady}>Archive Withdrawal</Button>
                </div>
              </div>
            ) : null}
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}>
              <Button subtle onClick={onBack} disabled={!onBack}>Go Back</Button>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
                {onWithdraw ? <Button danger onClick={onWithdraw}>Candidate Withdrew</Button> : null}
                {onSaveProgress ? <Button subtle onClick={onSaveProgress}>Save Progress</Button> : null}
                <Button primary onClick={onComplete} style={nextButtonStyle}>{completeLabel}</Button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
function formatDocumentBody(body) {
  return String(body || "")
    .split(NL + NL)
    .map((block) => block.trim())
    .filter(Boolean);
}

function EmailDocument({ title, subject, body, to, cc = "", onOpenDraft, onMarkSent, markSentLabel = "Mark Sent", attachmentLabel = "", onDownloadAttachment, attachmentNotice = "" }) {
  const width = useWindowWidth();
  const tight = width < 980;
  const [cleanView, setCleanView] = useState(false);
  const blocks = formatDocumentBody(body);
  const hasContent = Boolean(subject || body);
  const recipientLabel = to ? to : "No recipient set in Settings";
  const copyFullEmail = () => safeCopy(`To: ${to || ""}${cc ? `${NL}CC: ${cc}` : ""}${NL}Subject: ${subject || ""}${NL}${NL}${body || ""}`);

  return (
    <div style={{ border: `1px solid ${THEME.borderSoft}`, borderRadius: 6, overflow: "hidden", background: THEME.panel, boxShadow: THEME.shadow }}>
      {!cleanView ? (
        <div style={{ padding: 14, background: THEME.panelAlt, borderBottom: `1px solid ${THEME.borderSoft}`, display: "flex", flexDirection: tight ? "column" : "row", alignItems: tight ? "stretch" : "flex-start", justifyContent: "space-between", gap: 12 }}>
          <div>
            <div style={{ fontWeight: 900, color: THEME.text, fontSize: 15, display: "flex", alignItems: "center", gap: 6 }}>{title}</div>
            <div style={{ marginTop: 6, color: THEME.muted, fontSize: 13 }}><strong>To:</strong> {recipientLabel}</div>
            {cc ? <div style={{ marginTop: 4, color: THEME.muted, fontSize: 13 }}><strong>CC:</strong> {cc}</div> : null}
            <div style={{ marginTop: 4, color: THEME.muted, fontSize: 13 }}><strong>Subject:</strong> {subject || "No subject"}</div>
          </div>
          <div style={{ display: "grid", gap: 8, justifyItems: tight ? "stretch" : "end" }}>
            <div style={{ display: "flex", gap: 6, flexWrap: tight ? "wrap" : "nowrap", justifyContent: tight ? "flex-start" : "flex-end", alignItems: "center" }}>
              <strong style={{ color: THEME.muted, fontSize: 12 }}>Email:</strong>
              <Button primary onClick={() => { if (onDownloadAttachment) onDownloadAttachment(); openMailto(to, subject, body, onOpenDraft, { cc }); }} disabled={!hasContent} style={tight ? { flex: "1 1 140px" } : { padding: "7px 9px", fontSize: 11 }}>Open Email</Button>
              <Button subtle onClick={copyFullEmail} disabled={!hasContent} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>Copy Full Email</Button>
              <Button subtle onClick={() => safeCopy(subject)} disabled={!subject} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>Copy Subject</Button>
              <Button subtle onClick={() => safeCopy(body)} disabled={!body} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>Copy Email</Button>
            </div>
            <div style={{ display: "flex", gap: 6, flexWrap: tight ? "wrap" : "nowrap", justifyContent: tight ? "flex-start" : "flex-end", alignItems: "center" }}>
              <strong style={{ color: THEME.muted, fontSize: 12 }}>Additional Steps:</strong>
              <Button subtle onClick={() => setCleanView(true)} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>Clean View</Button>
              {onDownloadAttachment ? <Button subtle onClick={onDownloadAttachment} style={tight ? { flex: "1 1 150px" } : { padding: "7px 9px", fontSize: 11 }}>{attachmentLabel || "Download Attachment"}</Button> : null}
              <Button subtle onClick={() => downloadTextFile(`${title.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.txt`, `To: ${to || ""}${cc ? `${NL}CC: ${cc}` : ""}${NL}Subject: ${subject || ""}${NL}${NL}${body || ""}`)} disabled={!hasContent} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>Download</Button>
              {onMarkSent ? <Button subtle onClick={onMarkSent} style={tight ? { flex: "1 1 120px" } : { padding: "7px 9px", fontSize: 11 }}>{markSentLabel}</Button> : null}
            </div>
            {onDownloadAttachment ? <div style={{ color: THEME.amber, fontSize: 11, fontWeight: 850, maxWidth: 520, textAlign: tight ? "left" : "right" }}>{attachmentNotice || "Mailto cannot attach files automatically. Download the Excel file, then attach it to the email draft."}</div> : null}
          </div>
        </div>
      ) : (
        <div style={{ padding: 12, background: THEME.panelAlt, borderBottom: `1px solid ${THEME.borderSoft}`, display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center" }}>
          <strong style={{ color: THEME.text }}>{title}</strong>
          <Button subtle onClick={() => setCleanView(false)}>Show Controls</Button>
        </div>
      )}
      <div style={{ padding: tight ? 18 : 26, color: THEME.text, background: THEME.panel }}>
        <div style={{ maxWidth: 980, margin: "0 auto" }}>
          <h3 style={{ margin: "0 0 8px", fontSize: 18, color: THEME.text }}>{title}</h3>
          <div style={{ padding: "10px 0 16px", borderBottom: `1px solid ${THEME.borderSoft}`, color: THEME.muted, fontSize: 13, display: "grid", gap: 4 }}>
            <div><strong>To:</strong> {recipientLabel}</div>
            {cc ? <div><strong>CC:</strong> {cc}</div> : null}
            <div><strong>Subject:</strong> {subject || "No subject"}</div>
          </div>
          <div style={{ paddingTop: 18, display: "grid", gap: 14, lineHeight: 1.6, fontSize: 10, fontFamily: "Arial, sans-serif" }}>
            {blocks.length ? blocks.map((block, index) => {
              const lines = block.split(NL).filter(Boolean);
              const isHeading = block === block.toUpperCase() && block.length < 45 && !block.includes(":");
              const isBulletBlock = lines.length > 1 && lines.every((line) => line.trim().startsWith("-"));
              if (isHeading) return <h4 key={index} style={{ margin: "8px 0 0", color: THEME.primary, fontSize: 14, textTransform: "uppercase", letterSpacing: 0.5 }}>{block}</h4>;
              if (isBulletBlock) return <ul key={index} style={{ margin: 0, paddingLeft: 20 }}>{lines.map((line, lineIndex) => <li key={lineIndex}>{line.replace("- ", "")}</li>)}</ul>;
              return <p key={index} style={{ margin: 0, whiteSpace: "pre-wrap" }}>{block}</p>;
            }) : <p style={{ margin: 0, color: THEME.muted }}>No body generated yet.</p>}
          </div>
        </div>
      </div>
    </div>
  );
}

function EmptyState({ children }) {
  return <div style={{ border: `1px dashed ${THEME.border}`, borderRadius: 6, padding: 24, textAlign: "center", color: THEME.muted, background: THEME.panelAlt }}>{children}</div>;
}

function statTone(label, value, tone) {
  if (tone) return tone;
  const count = Number(value || 0);
  const key = String(label || "").toLowerCase();
  if (!count) return "Clear";
  if (key.includes("hired") || key.includes("placed")) return "Low";
  if (key.includes("high") || key.includes("risk") || key.includes("stuck") || key.includes("feedback")) return "High";
  if (key.includes("follow") || key.includes("awaiting")) return "Medium";
  return count >= 4 ? "High" : count >= 1 ? "Medium" : "Clear";
}

function statusToneFor(status) {
  const lower = String(status || "").toLowerCase();
  if (lower.includes("unresponsive") || lower.includes("rejected") || lower.includes("risk")) return "High";
  if (lower.includes("ready") || lower.includes("hired") || lower.includes("placed") || lower.includes("offer")) return "Low";
  if (lower.includes("interview")) return "Interview";
  return "Medium";
}

function MiniStat({ label, value, tone, onClick, compact }) {
  const Wrapper = onClick ? "button" : "div";
  const resolvedTone = statTone(label, value, tone);
  const showTone = resolvedTone && resolvedTone !== "Clear" && Number(value || 0) !== 0;
  const colors = badgeColors(resolvedTone);
  const [hover, setHover] = useState(false);
  return (
    <Wrapper
      type={onClick ? "button" : undefined}
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        width: "100%",
        minWidth: 0,
        textAlign: "left",
        border: `1px solid ${showTone ? colors.bg : THEME.borderSoft}`,
        borderRadius: 6,
        padding: compact ? "9px 12px" : "12px 14px",
        background: showTone ? colors.bg : THEME.panel,
        cursor: onClick ? "pointer" : "default",
        fontFamily: "Inter, Arial, sans-serif",
        boxShadow: hover && onClick ? "0 12px 24px rgba(15,23,42,0.10)" : THEME.shadow,
        minHeight: compact ? 58 : 72,
        boxSizing: "border-box",
        transform: hover && onClick ? "translateY(-2px)" : "translateY(0)",
        transition: "all 160ms ease",
      }}
    >
      <div style={{ color: showTone ? colors.color : THEME.muted, textTransform: "uppercase", fontSize: 10, fontWeight: 900, letterSpacing: 0.45, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{label}</div>
      <div style={{ marginTop: 5, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
        <strong style={{ fontSize: compact ? 18 : 20, lineHeight: 1, color: showTone ? colors.color : THEME.text }}>{value}</strong>
        {showTone ? <Badge tone={resolvedTone}>{resolvedTone}</Badge> : null}
      </div>
    </Wrapper>
  );
}

function playUiSound(kind = "tick", enabled = true) {
  if (!enabled || typeof window === "undefined") return;
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;
    const context = new AudioContextClass();
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    const now = context.currentTime;
    const isDing = kind === "ding";
    oscillator.type = isDing ? "sine" : "square";
    oscillator.frequency.setValueAtTime(isDing ? 920 : 650, now);
    if (isDing) oscillator.frequency.exponentialRampToValueAtTime(1240, now + 0.08);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(isDing ? 0.045 : 0.018, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + (isDing ? 0.22 : 0.055));
    oscillator.connect(gain);
    gain.connect(context.destination);
    oscillator.start(now);
    oscillator.stop(now + (isDing ? 0.24 : 0.06));
    setTimeout(() => context.close?.(), isDing ? 350 : 140);
  } catch {}
}

