    new: hotLeads.filter((lead) => !hotLeadIsClosed(lead) && ["New", "Outreach Needed"].includes(lead.outreachStatus)).length,
    sent: hotLeads.filter((lead) => !hotLeadIsClosed(lead) && ["Outreach Sent", "Second Outreach Sent", "Final Outreach Sent", "Email Sent", "Text Sent", "Booking Link Sent", "Call Attempted"].includes(lead.outreachStatus)).length,
    followUpDue: hotLeads.filter((lead) => hotLeadFollowUpDue(lead)).length,
