    clickedLinks: hotLeads.filter((lead) => !hotLeadIsClosed(lead) && hotLeadHasClickedLink(lead) && !hotLeadHasBookedCall(lead)).length,
    bookedCalls: hotLeads.filter((lead) => !hotLeadIsClosed(lead) && hotLeadHasBookedCall(lead)).length,
