    const archiveOutcome = String(item.archiveOutcome || "").trim();
    const closeOutType = String(item.closeOutType || "").trim();
    const activeHiredOutcome = ["Hired", "Onboarding", "Placed", "Offer Accepted"].includes(archiveOutcome);
    const closeOutStatus = ["Archived", "Closed", "Rejected", "Unresponsive", "Not Interested", "Withdrawn", "Withdrew"].includes(status);
    return Boolean(
      item.archived === true ||
      item.archivedAt ||
      item.closedAt ||
      status === "Archived" ||
      closeOutStatus ||
      closeOutType ||
      item.closeOutDetail ||
      item.archiveReason ||
      item.archiveNotes ||
      item.withdrawalReason ||
      (archiveOutcome && !activeHiredOutcome)
    );
