  function profileForHotLead(lead) {
    if (!lead) return null;
    const leadEmail = String(lead.email || "").trim().toLowerCase();
    const leadPhone = String(lead.phone || "").replace(/\D/g, "");
    const leadName = String(lead.candidateName || "").trim().toLowerCase();
    return tracker.find((item) => {
      const snapshot = item.formSnapshot || {};
      const itemEmail = String(item.candidateEmail || snapshot.emailAddress || "").trim().toLowerCase();
      const itemPhone = String(snapshot.phoneNumber || "").replace(/\D/g, "");
      const itemName = String(item.candidate || snapshot.fullName || "").trim().toLowerCase();
      return snapshot.sourceHotLeadId === lead.id
        || item.sourceHotLeadId === lead.id
        || (leadEmail && itemEmail === leadEmail)
        || (leadPhone && itemPhone === leadPhone)
        || (leadName && itemName === leadName);
    }) || null;
  }

