      rows: rows.sort((a, b) => hotLeadStatusRank(a) - hotLeadStatusRank(b) || Number(b.outreachAttempts || 0) - Number(a.outreachAttempts || 0) || String(a.candidateName || "").localeCompare(String(b.candidateName || ""))),
      total: rows.length,
