    if (hotLeadIsConverted(lead)) return "Intake";
    if (lead.outreachStatus === "Ready for Intake") return "Intake";
    if (lead.outreachStatus === "Booked" || lead.bookedScreeningDate) return "Scheduled";
    if (["Responded", "Ready for Intake"].includes(lead.outreachStatus) || lead.candidateInterestStatus === "Yes") return "Responded";
    if (Number(lead.outreachAttempts || 0) > 0 || ["Outreach Sent", "Second Outreach Sent", "Final Outreach Sent", "Email Sent", "Text Sent", "Call Attempted"].includes(lead.outreachStatus)) return "Outreach Sent";
