      bookingStatus: "Screen Scheduled",
      candidateInterested: "Booked",
      outreachStatus: "Booked",
      responseStatus: "Booked",
      outreachStopReason: "Screen scheduled",
      attemptOutcome: "Closed due to response or screen scheduled",
