      atsUpdateStatus: "Needed",
      atsNoteDraft: hotLeadAtsNoteFor({ ...item, outreachStatus: "Booked", bookedScreeningDate: draft.screenDate || item.bookedScreeningDate, bookedScreeningTime: draft.screenTime || item.bookedScreeningTime }, settings),
