  function resetOptionsSection() {
    if (!window.confirm("Reset Core Options to the built-in defaults?")) return;
    setSettings((prev) => ({ ...prev, options: JSON.parse(JSON.stringify(DEFAULT_SETTINGS.options)) }));
    clearSelectedForDelete("options");
  }

  function deleteAllOptionGroups() {
    if (!window.confirm("Clear all Core Option groups?")) return;
    optionGroupDefinitions().forEach((group) => group.onChange([]));
    clearSelectedForDelete("options");
  }

  function deleteSelectedOptionGroups() {
    const selected = selectedIdsFor("options");
    if (!selected.length) return;
    if (!window.confirm(`Clear ${selected.length} selected Core Option group${selected.length === 1 ? "" : "s"}?`)) return;
    optionGroupDefinitions().filter((group) => selected.includes(group.id)).forEach((group) => group.onChange([]));
    clearSelectedForDelete("options");
  }

